entries[31892] = { ["name"] = "Siegel des Blutes", ["text"] = "14% von Grundmana\nSofort\nAlle Nahkampfangriffe verursachen (0.48 * Mainhand weapon min damage) bis (0.48 * Mainhand weapon max damage) zusätzlichen Heiligschaden. Dabei verliert der Paladin aber Gesundheit entsprechend 31898% des gesamten verursachten Schadens. Hält 30 min lang an.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Gegner und verursacht sofort (0.26 * Mainhand weapon min damage + 0.11 * Attack power + 0.18 * Spell power) bis (0.26 * Mainhand weapon max damage + 0.11 * Attack power + 0.18 * Spell power) Heiligschaden auf Kosten von Gesundheit in Höhe von 33% des verursachten Schadens." }
entries[31893] = { ["name"] = "Siegel des Blutes", ["text"] = "Unbegrenzte Reichweite\nSofort\nAlle Nahkampfangriffe verursachen zusätzlichen Heiligschaden in Höhe von 48% des normalen Waffenschadens. Dabei verliert der Paladin aber Gesundheit entsprechend 31898% des gesamten verursachten Schadens.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Gegner und verursacht sofort Heiligschaden auf Kosten von Gesundheit in Höhe von 33% des verursachten Schadens." }
entries[31898] = { ["name"] = "Richturteil des Blutes", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Entfesselung der Energie dieses Siegels richtet einen Feind und verursacht sofort Heiligschaden, wofür der Zaubernde 33% des verursachten Schadens erleidet." }
