entries[32502] = { ["name"] = "Netherzorngamaschen", ["text"] = "Wirken in 45 sek.\nReagenzien:\nSchweres Knotenhautleder (8), Kristalldurchdrungenes Leder (12), Urwasser (5), Urmana (5), Runenfaden (2)\nNetherzorngamaschen\nWird beim Anlegen gebunden\nBeine Kette\n527 Rüstung\n+37 Ausdauer\n\nRoter Sockel\nBlauer Sockel\nBlauer Sockel\nSockelbonus: +4 Kritische Trefferwertung\n\nHaltbarkeit 90 / 90\n67\nAnlegen: Erhöht die Zaubermacht um 29.\nAnlegen: Stellt alle 5 Sek. 13 Mana wieder her.\n\nNetherzorn (0/3)\nBenötigt Lederverarbeitung\n(350) Netherzorngürtel\nNetherzornstiefel\nNetherzorngamaschen" }
entries[32503] = { ["name"] = "Netherzornstiefel", ["text"] = "Wirken in 45 sek.\nReagenzien:\nSchweres Knotenhautleder (6), Kristalldurchdrungenes Leder (10), Urwasser (4), Urmana (4), Runenfaden (2)\nNetherzornstiefel\nWird beim Anlegen gebunden\nFüße Kette\n392 Rüstung\n+36 Ausdauer\n\nBlauer Sockel\nRoter Sockel\nSockelbonus: +3 Kritische Trefferwertung\n\nHaltbarkeit 60 / 60\n69\nAnlegen: Erhöht die Zaubermacht um 21.\nAnlegen: Stellt alle 5 Sek. 9 Mana wieder her.\n\nNetherzorn (0/3)\nBenötigt Lederverarbeitung\n(350) Netherzorngürtel\nNetherzornstiefel\nNetherzorngamaschen" }
entries[32504] = { ["name"] = "Machtwort: Schutz", ["text"] = "356 Mana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 1338 magischen Schaden. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
