entries[32590] = { ["name"] = "Teufelskanone benutzen", ["text"] = "5 Meter Reichweite\nWirken in 5 sek.\nDreht die Teufelskanone und feuert auf das Konstruktionslager: Hass." }
entries[32591] = { ["name"] = "Teufelskanone benutzen", ["text"] = "5 Meter Reichweite\nWirken in 5 sek.\nDreht die Teufelskanone und feuert auf das Konstruktionslager: Furcht." }
entries[32592] = { ["name"] = "Massenbannung", ["text"] = "30 Meter Reichweite\nSofort\nBannt Magie in einem Radius von 15 Metern. Entfernt 1 schädlichen Zauber von jedem befreundeten Ziel und 1 nützlichen Zauber von jedem gegnerischen Ziel. Wirkt auf bis zu 10 befreundete und 10 gegnerische Ziele. Dieser Bannzauber ist mächtig genug, magische Effekte zu entfernen, die normalerweise nicht gebannt werden können." }
entries[32593] = { ["name"] = "Erdschild", ["text"] = "15% von Grundmana 40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild, der die erhöhte Zauberdauer oder verringerte Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um 205 heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 6 Aufladungen. Hält 10 min lang an. Der Erdschild kann immer nur auf einem Ziel gleichzeitig aktiv sein, und auf jedem Ziel kann nur ein Elementarschild aktiv sein.\n(3.5s Abklingzeit)" }
entries[32594] = { ["name"] = "Erdschild", ["text"] = "15% von Grundmana 40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild, der die erhöhte Zauberdauer oder verringerte Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um 270 heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 6 Aufladungen. Hält 10 min lang an. Der Erdschild kann immer nur auf einem Ziel gleichzeitig aktiv sein, und auf jedem Ziel kann nur ein Elementarschild aktiv sein.\n(3.5s Abklingzeit)" }
entries[32595] = { ["name"] = "Machtwort: Schild", ["text"] = "110 Mana 40 Meter Reichweite\nSofort\nUmgibt einen Verbündeten mit einem Schild, der bis zu 30 sec lang bestehen bleibt und maximal 411 körperlichen oder magischen Schaden absorbiert. Solange der Schild hält, werden Zauber nicht durch körperliche Angriffe unterbrochen." }
entries[32599] = { ["name"] = "Besänftigen", ["text"] = "Sofort\nReduziert Eure Bedrohung gegenüber Feinden im Umkreis von 30 Metern und macht es weniger wahrscheinlich, dass diese Euch angreifen." }
