entries[32612] = { ["name"] = "Unsichtbarkeit", ["text"] = "Sofort\nLässt den Zaubernden im Verlauf von 3 sec bis zur Unsichtbarkeit verblassen und verringert mit jeder Sekunde die Bedrohung. Der Effekt wird abgebrochen, wenn Ihr selbst Aktionen ausführt oder Ziel solcher werdet. Während Ihr unsichtbar seid, könnt ihr nur andere unsichtbare Ziele wahrnehmen, und solche, die Unsichtbare sehen können. Hält 20 sec lang an." }
