entries[32674] = { ["name"] = "Schild des Rächers", ["text"] = "45 Mana 30 Meter Reichweite\nWirken in 1 sek.\nSchleudert einen heiligen Schild auf den Gegner, der 270 to 330 Heiligschaden zufügt, ihn benommen macht, und dann auf weitere nahe Gegner überspringt. Wirkt auf insgesamt 2 Ziele." }
entries[32675] = { ["name"] = "Schattengeschosse", ["text"] = "50 Mana 100 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nSchleudert Schattengeschosse auf einen Feind und verursacht 5 sec lang pro Sekunde Schattenschaden." }
entries[32677] = { ["name"] = "Schattengeschosse", ["text"] = "30 Meter Reichweite\nSofort\nSchleudert Schattenblitze auf einen Gegner und fügt Schattenschaden zu." }
entries[32678] = { ["name"] = "Kürschnerei", ["text"] = "5 Meter Reichweite\nWirken in 1.5 sek.\nTools:\nKürschnermesser\nMeisterliche Fertigkeiten der Kürschnerei, der Vorbereitung von Häuten von Wildtieren für die Lederverarbeitung. Verleiht eine potenzielle Kürschnerfertigkeit von 375. Es wird ein Kürschnermesser benötigt." }
