entries[32690] = { ["name"] = "Arkaner Blitzschlag", ["text"] = "150 Mana 30 Meter Reichweite\nWirken in 1.5 sek. 6 sek. Abklingzeit\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 5 Ziele aus und verursacht bei jedem folgenden Ziel immer größeren Arkanschaden. Bringt einen Gegner zum Schweigen und hindert ihn 4 sec lang am Zauberwirken." }
entries[32691] = { ["name"] = "Zauberschock", ["text"] = "100 Mana 30 Meter Reichweite\nSofort\nKontert den Zauber eines Feindes und verhindert 6 sec lang, dass der Feind den gleichen Zauber noch einmal wirkt. Führt zu einem hohen Maß an Bedrohung." }
